@CategoryID_6c1b11af9065 UNIQUEIDENTIFIER,
@UserQuestion_6c1b11af9065 NVARCHAR(MAX),
@Description_6c1b11af9065 NVARCHAR(MAX),
@SQL_6c1b11af9065 NVARCHAR(MAX),
@TechnicalDescription_6c1b11af9065 NVARCHAR(MAX),
@OriginalSQL_6c1b11af9065 NVARCHAR(MAX),
@Feedback_6c1b11af9065 NVARCHAR(MAX),
@Status_6c1b11af9065 NVARCHAR(15),
@QualityRank_6c1b11af9065 INT,
@ExecutionCostRank_6c1b11af9065 INT,
@UsesTemplate_6c1b11af9065 BIT,
@AuditQueryRuns_6c1b11af9065 BIT,
